pub fn build(self) -> Result<LintRunner, String> {
    let directives_coordinator = DirectivesStore::new();

    let type_aware_linter = if self.type_aware_enabled {
        match TsGoLintState::try_new(
            self.lint_service_options.cwd(),
            self.regular_linter.config.clone(),
            self.fix_kind,
        ) {
            Ok(state) => Some(
                state
                    .with_silent(self.silent)
                    .with_type_check(self.type_check)
                    .with_type_check_only(self.type_check_only)
                    .with_timings(self.timings)
                    .with_ignore_fixes(self.with_ignore_fixes),
            ),
            Err(e) => return Err(e),
        }
    } else {
        None
    };

fn js_config_not_supported_diagnostic(path: &Path) -> OxcDiagnostic {
    OxcDiagnostic::error(format!(
        "JavaScript/TypeScript config file ({}) found but JS runtime not available.",
        path.to_string_lossy().cow_replace('\\', "/")
    ))
    .with_help("Run oxlint via the npm package, or use JSON config files (.oxlintrc.json or .oxlintrc.jsonc).")
}
